(1, 'iPhone Unlocking Store', 'iphoneunlockingstore', 'iPhone and device unlocking services', 'https://api.iphoneunlockingstore.com', 'https://iphoneunlockingstore.com/docs', '{\r\n  \"services\": {\r\n    \"endpoint\": \"/api/v2\",\r\n    \"method\": \"POST\",\r\n    \"payload\": {\r\n      \"action\": \"services\"\r\n    },\r\n    \"map\": {\r\n      \"id\": \"service\",\r\n      \"name\": \"name\",\r\n      \"category\": \"category\",\r\n      \"type\": \"type\",\r\n      \"price\": \"rate\",\r\n      \"min\": \"min\",\r\n      \"max\": \"max\"\r\n    }\r\n  }\r\n}', 'active', '2025-12-31 14:48:03', '2025-12-31 17:39:28'),
(2, 'SMS-Man', 'sms-man', 'SMS verification and OTP services', 'https://api.sms-man.com', 'https://sms-man.com/docs', '{\n    \"services\": {\n        \"endpoint\": \"\\/applications\",\n        \"method\": \"GET\",\n        \"auth_param\": \"token\",\n        \"response_type\": \"keyed_object\",\n        \"map\": {\n            \"id\": \"id\",\n            \"name\": \"title\"\n        },\n        \"defaults\": {\n            \"category\": \"SMS-Man\",\n            \"type\": \"sms\",\n            \"min\": 1,\n            \"max\": 1\n        }\n    },\n    \"pricing\": {\n        \"endpoint\": \"\\/get-prices\",\n        \"method\": \"GET\",\n        \"auth_param\": \"token\",\n        \"payload\": {\n            \"country\": \"{default_country}\"\n        },\n        \"response_type\": \"keyed_object\",\n        \"map\": {\n            \"service_id\": \"__key\",\n            \"rate\": \"cost\"\n        }\n    }\n}', 'active', '2025-12-31 14:48:03', '2026-01-02 14:41:58'),
(3, 'ESIM Access', 'esim-access', 'eSIM and mobile connectivity services', 'https://api.esimaccess.com', 'https://esimaccess.com/docs', NULL, 'active', '2025-12-31 14:48:03', '2025-12-31 14:48:03'),
(5, 'PAYTOSMM', 'paytosmm', 'smm pannel', 'https://paytosmm.com/api/v2', 'https://docs.paytosmm.com/api', '{\r\n  \"services\": {\r\n    \"endpoint\": \"/api/v2\",\r\n    \"method\": \"POST\",\r\n    \"payload\": {\r\n      \"action\": \"services\"\r\n    },\r\n    \"map\": {\r\n      \"id\": \"service\",\r\n      \"name\": \"name\",\r\n      \"category\": \"category\",\r\n      \"type\": \"type\",\r\n      \"price\": \"rate\",\r\n      \"min\": \"min\",\r\n      \"max\": \"max\"\r\n    }\r\n  }\r\n}', 'active', '2025-12-31 17:29:44', '2025-12-31 17:44:22'),
(6, 'smm24h', 'smm24h', 'smm pannel', 'https://smm24h.com', 'https://smm24h.com/api', '{\n    \"services\": {\n        \"endpoint\": \"\\/api\\/v2\",\n        \"method\": \"POST\",\n        \"payload\": {\n            \"action\": \"services\"\n        },\n        \"map\": {\n            \"id\": \"service\",\n            \"name\": \"name\",\n            \"category\": \"category\",\n            \"type\": \"type\",\n            \"price\": \"rate\",\n            \"min\": \"min\",\n            \"max\": \"max\"\n        }\n    }\n}', 'active', '2026-01-03 01:20:07', '2026-01-03 01:22:22'),
(7, 'mastpanel', 'mastpanel', 'smm panel', 'http://mastpanel.online/', '', '{\n    \"services\": {\n        \"endpoint\": \"\\/api\\/v2\",\n        \"method\": \"POST\",\n        \"payload\": {\n            \"action\": \"services\"\n        },\n        \"map\": {\n            \"id\": \"service\",\n            \"name\": \"name\",\n            \"category\": \"category\",\n            \"type\": \"type\",\n            \"price\": \"rate\",\n            \"min\": \"min\",\n            \"max\": \"max\"\n        }\n    }\n}', 'active', '2026-01-03 01:37:58', '2026-01-03 01:41:16');
